import{_ as a,o as s,c as n,ag as t}from"./chunks/framework.PVHj0As1.js";const p="/pub-blog/assets/image-20250302215651874.DTBejhf8.png",i="/pub-blog/assets/image-20250302215721782.DkklMnuV.png",o="/pub-blog/assets/image-20250302215841709.CMKpSg0C.png",g="/pub-blog/assets/image-20250302215925573.T5zcqkLk.png",r="/pub-blog/assets/image-20250302220338797.CjsHb69M.png",m="/pub-blog/assets/image-20250302220546641.B4v22830.png",l="/pub-blog/assets/image-20250302220703337.0FG3FGDM.png",c="/pub-blog/assets/image-20250302220858577.B19jKEVC.png",_="/pub-blog/assets/image-20250302220941452.nZgeMmbw.png",d="/pub-blog/assets/image-20250302221028285.B7xkc1IT.png",h="/pub-blog/assets/image-20250302221239991.B0Nf7jrH.png",b="/pub-blog/assets/image-20250302221349677.DJELttYc.png",T=JSON.parse('{"title":"小白快速上手 腾讯云AI代码助手  deepseek","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/腾讯云AI代码助手 帮你快速熟悉项目/腾讯云AI代码助手 帮你快速熟悉项目.md","filePath":"AI人工智能/腾讯云AI代码助手 帮你快速熟悉项目/腾讯云AI代码助手 帮你快速熟悉项目.md","lastUpdated":1741103168000,"__rawMarkdown":"# 小白快速上手 腾讯云AI代码助手  deepseek\\n\\n**腾讯云 AI 代码助手**是由腾讯云自研的一款开发编程提效辅助工具，基于混元代码大模型，提供技术对话、代码补全、代码诊断和优化等能力。\\n\\n今日，**腾讯云AI代码助手** 也是上线了 满血版deepseekR1模型，大家再也不用忍受官网慢吞吞的速度了—— **请刷新重试🤮**\\n\\n\\n\\n\\n\\n## 下载安装或者更新腾讯云AI代码助手\\n\\n如果还没有下载**腾讯云AI代码助手**的同学，打开vscode的拓展插件，搜索安装即可。\\n\\n![image-20250302215651874](assets/image-20250302215651874.png)\\n\\n如果之前已经安装了，记得要更新到最新版本\\n\\n![image-20250302215721782](assets/image-20250302215721782.png)\\n\\n## 选择 deepseek R1 \\n\\n首次使用的同学，需要登录的，成功登录后可以看到以下内容。\\n\\n![image-20250302215841709](assets/image-20250302215841709.png)\\n\\n这里就可以切换大模型 **tencent:deepseek-r1**\\n\\n![image-20250302215925573](assets/image-20250302215925573.png)\\n\\n\\n\\n## 玩转项目\\n\\n这里刚好有个小伙伴发来一个项目，我们就利用**腾讯云 AI 代码助手**来好好玩转一下这个项目\\n\\n## 解读项目\\n\\n这个项目运行起来还挺好看的\\n\\n![image-20250302220338797](assets/image-20250302220338797.png)\\n\\n我们来让AI助手帮我们解读一下这个项目。\\n\\n使用**@workspace** 访问当前工作目录，让它解读一下这个项目。\\n\\n![image-20250302220546641](assets/image-20250302220546641.png)\\n\\n可以看到它很认真的帮我分析和解读了当前的项目技术架构\\n\\n![image-20250302220703337](assets/image-20250302220703337.png)\\n\\n## 对话项目\\n\\n这个时候，我想要知道在哪里可以修改项目的主题颜色，就可以直接问它了。\\n\\n![image-20250302220858577](assets/image-20250302220858577.png)\\n\\n然后它贴心的给了我们两种方案\\n\\n![image-20250302220941452](assets/image-20250302220941452.png)\\n\\n这里可以点击 **Apply**  就可以把想要的代码应用到项目对应的文件中。\\n\\n![image-20250302221028285](assets/image-20250302221028285.png)\\n\\n## 解释代码\\n\\n代码内，想要了解某些代码的作用，选中它们，然后选择**解释代码**即可。\\n\\n![image-20250302221239991](assets/image-20250302221239991.png)\\n\\n然后得到了很详细的解释\\n\\n![image-20250302221349677](assets/image-20250302221349677.png)\\n\\n## 其他玩法\\n\\n还有很多其他的玩法，可以参考[链接](https://marketplace.visualstudio.com/items?itemName=Tencent-Cloud.coding-copilot)"}'),u={name:"AI人工智能/腾讯云AI代码助手 帮你快速熟悉项目/腾讯云AI代码助手 帮你快速熟悉项目.md"};function k(A,e,I,f,q,x){return s(),n("div",null,[...e[0]||(e[0]=[t("",37)])])}const C=a(u,[["render",k]]);export{T as __pageData,C as default};
